namespace LinQL.StrawberryShake;

using System.Text.Json;
using global::StrawberryShake;

/// <summary>
/// Configuration for a <see cref="StrawberryShakeLinQLClient"/>.
/// </summary>
public sealed class LinQLStrawberryShakeOptions
{
    /// <summary>
    /// Gets the LinQL configuration used to translate expressions.
    /// </summary>
    public LinQLOptions LinQL { get; init; } = new();

    /// <summary>
    /// Gets the serializer options used to deserialise responses before they are projected.
    /// </summary>
    /// <remarks>
    /// Add the interface registrations generated by LinQL (usually
    /// <c>new JsonSerializerOptions().WithKnownInterfaces()</c>) when querying interfaces or unions.
    /// </remarks>
    public JsonSerializerOptions Serializer { get; init; } = new(JsonSerializerDefaults.Web);

    /// <summary>
    /// Gets the execution strategy used when the connection supports operation caching.
    /// </summary>
    public ExecutionStrategy Strategy { get; init; } = ExecutionStrategy.NetworkOnly;
}
